n = 4000001
s = [i for i in range(n + 1)]

def test():
	p = 2
	while p * p <= n:
		if s[p] == p:
			for i in range(p * p, n + 1, p):
				if s[i] >= p:
					s[i] = p
		p += 1
test()

def f(x):
	d = dict()
	while x != 1:
		t = s[x]
		if t in d:
			d[t] += 1
		else:
			d[t] = 1
		x = x // t
	return d

def A(k):
	ans = 1
	d = f(4 * k + 1)
	for i in d:
		ans *= d[i] + 1 - d[i] / i
	return round(4 * k + (ans - 1) / 2 * (4 * k + 1))
L = [1]
for i in range(1, 10 ** 6 + 1):
	L.append(A(i))
